-- BankJobz: 39 real non-technical bank and credit union openings (gathered Nov 1, 2026).
-- Paste into the Neon SQL Editor and click Run. Safe to run more than once: already-loaded
-- listings are skipped.
ON CONFLICT (source_url) DO NOTHING;

-- Check: jobs on the board by department.
SELECT category, COUNT(*) AS open_jobs FROM jobs WHERE status = 'open' GROUP BY category ORDER BY open_jobs DESC;
